package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.TreeMap;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * LMDB end-to-end guard for the sub-select scope boundary: whatever plan the packed planner picks, a sub-select inside
 * an OPTIONAL or an EXISTS body must never see the variables of the enclosing group that it does not project, and an
 * EXISTS body's projected variables are substituted before the sub-select's LIMIT. Each query runs three times so the
 * cold plan and the cached plan are both checked.
 */
class LmdbSubSelectScopeTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String PREFIX = "PREFIX : <urn:ex:>\n";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private static IRI iri(String local) {
		return VF.createIRI("urn:ex:" + local);
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(?t != ?s)" })
	void optionalOverLimitedSubSelectIsEvaluatedIndependently(String condition) {
		add(iri("a"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("r"), VF.createLiteral(1));
		add(iri("d"), iri("r"), VF.createLiteral(2));
		String query = PREFIX + """
				SELECT ?s ?x ?t WHERE {
				  ?s :p ?x
				  OPTIONAL { { SELECT ?t ?x WHERE { ?t :r ?x } ORDER BY ?x LIMIT 1 } %s }
				}
				""".formatted(condition);
		assertRepeatedly(query, List.of("{s=urn:ex:a, x=2}"));
	}

	@ParameterizedTest(name = "condition={0}")
	@ValueSource(strings = { "", "FILTER(?n > 0 && BOUND(?s))" })
	void optionalOverAggregateSubSelectIsEvaluatedIndependently(String condition) {
		add(iri("a"), iri("p"), iri("o1"));
		add(iri("t1"), iri("r"), iri("o1"));
		add(iri("t2"), iri("r"), iri("o2"));
		String query = PREFIX + """
				SELECT ?s ?n WHERE {
				  ?s :p ?o
				  OPTIONAL { { SELECT (COUNT(?o) AS ?n) WHERE { ?t :r ?o } } %s }
				}
				""".formatted(condition);
		assertRepeatedly(query, List.of("{n=2, s=urn:ex:a}"));
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverSubSelectDoesNotSubstituteNonProjectedVariable(boolean negated) {
		add(iri("a"), iri("p"), VF.createLiteral(1));
		add(iri("c"), iri("r"), VF.createLiteral(2));
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { { SELECT ?t WHERE { ?t :r ?x } } }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		assertRepeatedly(query, negated ? List.of() : List.of("{s=urn:ex:a}"));
	}

	@ParameterizedTest(name = "negated={0}")
	@ValueSource(booleans = { false, true })
	void existsOverLimitedSubSelectSubstitutesProjectedVariableBeforeTheLimit(boolean negated) {
		add(iri("a"), iri("p"), VF.createLiteral(2));
		add(iri("c"), iri("r"), VF.createLiteral(1));
		add(iri("d"), iri("r"), VF.createLiteral(2));
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER %s { SELECT ?x WHERE { ?t :r ?x } ORDER BY ?x LIMIT 1 }
				}
				""".formatted(negated ? "NOT EXISTS" : "EXISTS");
		assertRepeatedly(query, negated ? List.of() : List.of("{s=urn:ex:a}"));
	}

	@Test
	void lateralSubSelectSeesTheSubstitutedProjectedVariableInBound() {
		addLabelData();
		String query = PREFIX + """
				SELECT ?s ?lbl WHERE {
				  ?s :p ?x
				  LATERAL { SELECT ?x ?lbl WHERE { ?t :label ?lbl FILTER(!BOUND(?x) || ?t = ?x) } }
				}
				""";
		assertRepeatedly(query, List.of("{lbl=one, s=urn:ex:a}"));
	}

	@Test
	void notExistsSubSelectSeesTheSubstitutedProjectedVariableInBound() {
		addLabelData();
		String query = PREFIX + """
				SELECT ?s WHERE {
				  ?s :p ?x
				  FILTER NOT EXISTS { SELECT ?x WHERE { ?t :label ?l FILTER(!BOUND(?x)) } }
				}
				""";
		assertRepeatedly(query, List.of("{s=urn:ex:a}"));
	}

	private void addLabelData() {
		add(iri("a"), iri("p"), iri("k1"));
		add(iri("k1"), iri("label"), VF.createLiteral("one"));
		add(iri("k2"), iri("label"), VF.createLiteral("two"));
	}

	private void add(IRI subject, IRI predicate, Value object) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(subject, predicate, object);
		}
	}

	private void assertRepeatedly(String query, List<String> expected) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			for (int run = 0; run < 3; run++) {
				List<String> rows = rows(connection, query);
				int attempt = run;
				assertThat(rows)
						.as(() -> "run " + attempt + "\n"
								+ connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized))
						.containsExactlyElementsOf(expected);
			}
		}
	}

	private static List<String> rows(SailRepositoryConnection connection, String query) {
		List<String> rows = new ArrayList<>();
		try (TupleQueryResult result = connection.prepareTupleQuery(query).evaluate()) {
			while (result.hasNext()) {
				BindingSet bindingSet = result.next();
				TreeMap<String, String> sorted = new TreeMap<>();
				for (String name : bindingSet.getBindingNames()) {
					Value value = bindingSet.getValue(name);
					if (value != null) {
						sorted.put(name, value.stringValue());
					}
				}
				rows.add(sorted.toString());
			}
		}
		rows.sort(Comparator.naturalOrder());
		return rows;
	}
}
